/* Master Config */

/* ---- Configuration ---- */

/* ---- Load wallust colors ---- */
@import "colors.rasi"

configuration {
	modi:                       "drun,run,filebrowser";
    show-icons:                 true;
    display-drun:               "Apps";
    display-run:                "Run";
    display-filebrowser:        "Files";
    display-window:             "Windows";
  	drun-display-format:        "{name}";
	  hover-select:               true;
	  me-select-entry:            "MouseSecondary";
    me-accept-entry:            "MousePrimary";
	  window-format:              "{w} · {c} · {t}";
	  dpi:						1;
}



/* ---- Global Properties ---- */
* {

    background-alt:              @background; // Buttons background
    selected:                    @primary; // Button selected
    active:                      @primary-container; // Window activated
    urgent:                      @tertiary-container; // When hovering the activated window (maybe more?)

    text-selected:               @on-primary-container;
    text-color:                  @on-surface;
    border-color:                @primary;
}

/* ---- Window ---- */
window {
    // Default
    enabled:                    true;
    fullscreen:                 false;
    transparency:               "real";
    cursor:                     "default";
    spacing:                    0px;
    border:                     0px;
    border-radius:              14px;
    location:                   center;
    anchor:                     center;

    // Style Values
    width:                      44%;
    background-color:           @surface-container-lowest;
}

/* ----- Main Box ----- */
mainbox {
    padding:			5px;
    enabled:                     true;
    orientation:                 vertical;
    children:                    [ "inputbar", "listbox" ];
    background-color:            @surface-container-lowest;
}


/* ---- Inputbar ---- */
inputbar {
    enabled:                     true;
    padding:                     0px 0px 0px 0px;
    margin:                      10px;
    background-color:            transparent;
    orientation:                 horizontal;
    children:                    ["entry", "dummy", "mode-switcher" ];

}

/* ---- Entry input ---- */
entry {
    font: "JetBrainsMono Nerd Font 13";
    enabled:                     true;
    expand:                      false;
    width:                       100%;
    padding:                     0px;
    border-radius:               1px;
    background-color:            @surface-container-lowest;
    text-color:                  @on-surface;
    cursor:                      text;
    placeholder:                 "  Search "; // << Search symbol
    placeholder-color:           @on-surface-variant;
}

/* ---- Listbox ---- */
listbox {
    spacing:                     10px;
    padding:                     0px;
    background-color:            transparent;
    orientation:                 vertical;
    children:                    ["listview" ];
}

/* ---- Listview ---- */
listview {
    enabled:                     true;
    columns:                     1;
    lines:                       8;
    cycle:                       true;
    dynamic:                     true;
    scrollbar:                   true;
    layout:                      vertical;
    reverse:                     false;
    fixed-height:                false;
    fixed-columns:               true;    
    spacing:                     8px;
    background-color:            transparent;

//  Adapt rofi theme
    border:                      0px;
}

/* ---- Dummy ---- */
dummy {
    expand:                      true;
    background-color:            transparent;
}

/* ---- Mode Switcher ---- */
mode-switcher{
    enabled:                     true;
    spacing:                     10px;
    background-color:            transparent;
}
button {
    width:                       4%;
    padding:                     0px;
    border-radius:               7px;
    background-color:            @primary;
    text-color:                  @on-primary-container;
    cursor:                      pointer;
}
button selected {
    background-color:            @primary-container;
    text-color:                  @on-primary-container;
}

/* ---- Scrollbar ---- */
scrollbar {
    width:        4px;
    border:       0;
    handle-color: @primary;
    handle-width: 8px;
    padding:      0;
    border-radius:      12px;
}

/* ---- Elements ---- */
element {
    enabled:                     true;
    spacing:                     10px;
    padding:                     5px;
    border-radius:               5px;
    background-color:            transparent;
    cursor:                      pointer;
}

element normal.normal {
    background-color:            inherit;
    text-color:                  inherit;
}
element normal.urgent {
    background-color:            @tertiary-container;
    text-color:                  @on-tertiary-container;
}
element normal.active {
    background-color:            @primary-container;
    text-color:                  @on-primary-container;
}

element selected.normal {
    background-color:            @primary;
    text-color:                  @on-primary;
}
element selected.urgent {
    background-color:            @tertiary-container;
    text-color:                  @on-tertiary-container;
}
element selected.active {
    background-color:            @tertiary-container;
    text-color:                  @on-tertiary-container;
}
// Adapt rofi theme
element alternate.normal {
    background-color:            transparent;
    text-color:                  inherit;
}
element alternate.urgent {
    background-color:            transparent;
    text-color:                  inherit;
}
element alternate.active {
    background-color:            transparent;
    text-color:                  inherit;
}
element-icon {
    background-color:            transparent;
    text-color:                  inherit;
    size:                        20px;
    cursor:                      inherit;
}
element-text {
    background-color:            transparent;
    text-color:                  inherit;
    cursor:                      inherit;
    vertical-align:              0.5;
    horizontal-align:            0.0;

}

/* ---- Message ---- */
message {
    background-color:            transparent;
    border:                      0px;
}
textbox {
    padding:                     4px;
    border-radius:               12px;
    background-color:            @background;
    text-color:                  @surface;
    vertical-align:              0.5;
    horizontal-align:            0.0;
}
error-message {
    padding:                     12px;
    border-radius:               20px;
    background-color:            @background;
    text-color:                  @surface;
}

